/**
 * Bulk-safe trigger for Contact.
 *
 * The trigger itself contains no SOQL and no DML; all logic is delegated to
 * ContactTriggerHandler. Per chunk of up to 200 contacts the total cost of the
 * trigger logic is at most 2 SOQL queries (one in the before context, one in
 * the after context) and at most 1 DML statement.
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {

    if (Trigger.isBefore) {
        if (Trigger.isInsert) {
            ContactTriggerHandler.handleBeforeInsert(Trigger.new);
        } else if (Trigger.isUpdate) {
            ContactTriggerHandler.handleBeforeUpdate(Trigger.new);
        }
    }

    if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.handleAfterInsert(Trigger.new);
    }
}
