/**
 * Handler for ContactTrigger. All SOQL and DML for the trigger lives here and is
 * fully bulkified: one SOQL query per event context (max 2 for an insert, 1 for
 * an update) and at most one DML statement (the bulk account update in after insert).
 *
 * Behaviour preserved from the original trigger:
 *  - Before insert/update: contacts with a blank MailingCountry are defaulted from
 *    their account's BillingCountry; on insert only, a blank LeadSource is defaulted
 *    from the account's AccountSource.
 *  - After insert: if an inserted contact has a phone and its account has no phone,
 *    the account gets the contact's phone. When several inserted contacts of the
 *    same account have a phone and the account has none, the first such contact in
 *    trigger order wins.
 */
public inherited sharing class ContactTriggerHandler {

    /**
     * before insert: default MailingCountry and LeadSource from the related account.
     */
    public static void handleBeforeInsert(List<Contact> newRecords) {
        populateContactFromAccount(newRecords, true);
    }

    /**
     * before update: default MailingCountry from the related account.
     */
    public static void handleBeforeUpdate(List<Contact> newRecords) {
        populateContactFromAccount(newRecords, false);
    }

    /**
     * after insert: copy the phone of the first contact (in trigger order) to its
     * account, but only when the account currently has no phone.
     */
    public static void handleAfterInsert(List<Contact> newRecords) {
        copyPhoneToAccountsWithoutPhone(newRecords);
    }

    /**
     * Shared before-logic. One bulkified SOQL query for the whole chunk, then the
     * field defaults are applied in memory (no DML; records are saved by the insert/update).
     */
    private static void populateContactFromAccount(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact contact : contacts) {
            if (contact.AccountId != null) {
                accountIds.add(contact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL #1 (before context): fetch all referenced accounts in one query.
        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact contact : contacts) {
            if (contact.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }
            if (String.isBlank(contact.MailingCountry)) {
                contact.MailingCountry = account.BillingCountry;
            }
            if (isInsert && String.isBlank(contact.LeadSource)) {
                contact.LeadSource = account.AccountSource;
            }
        }
    }

    /**
     * After-insert logic. One bulkified SOQL query plus one bulkified update DML.
     */
    private static void copyPhoneToAccountsWithoutPhone(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact contact : contacts) {
            if (contact.AccountId != null && String.isNotBlank(contact.Phone)) {
                accountIds.add(contact.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL #2 (after context): fetch current phones of all referenced accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        // Iterate in trigger order; the first contact with a phone per account wins.
        Map<Id, String> firstPhoneByAccountId = new Map<Id, String>();
        for (Contact contact : contacts) {
            if (contact.AccountId == null || String.isBlank(contact.Phone)) {
                continue;
            }
            Account account = accountsById.get(contact.AccountId);
            if (account == null || String.isNotBlank(account.Phone)) {
                continue;
            }
            if (!firstPhoneByAccountId.containsKey(contact.AccountId)) {
                firstPhoneByAccountId.put(contact.AccountId, contact.Phone);
            }
        }

        if (firstPhoneByAccountId.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : firstPhoneByAccountId.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                Phone = firstPhoneByAccountId.get(accountId)
            ));
        }

        // Single bulkified DML statement for the whole chunk.
        update accountsToUpdate;
    }
}
