/**
 * Schedulable purge job for integration logs stored in FB_Integration_Log__c.
 *
 * Retention policy enforced on every run:
 *   - Logs created more than 30 days ago are deleted, unless Level__c = 'ERROR'.
 *   - Logs with Level__c = 'ERROR' are kept until they are more than 180 days old.
 *   - A blank Level__c is treated as a non-ERROR log and follows the 30-day rule.
 *
 * Governor-limit safety: a single scheduled run deletes up to FAST_PATH_LIMIT rows
 * synchronously. If more rows than that are due for deletion (e.g. the first run
 * after go-live), the remainder is drained by a batch run of this same class, so
 * neither the 50,000 queried-rows limit nor the 10,000 DML-rows limit can be hit,
 * no matter how large the backlog is.
 *
 * Usage:
 *   Id cronTriggerId = LogPurgeJob.scheduleNightly(); // daily at 02:00
 */
public inherited sharing class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /** Name the job appears under on the Scheduled Jobs page. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** Seconds Minutes Hours Day-Of-Month Month Day-Of-Week: 02:00:00 every day. */
    private static final String CRON_NIGHTLY = '0 0 2 * * ?';

    /** Rows deleted in the synchronous fast path; headroom under the 10,000 DML row limit. */
    @TestVisible private static final Integer FAST_PATH_LIMIT = 9000;

    /** Rows deleted per batch chunk. */
    @TestVisible private static final Integer BATCH_SIZE = 2000;

    /** No-argument constructor, as required for schedulable jobs. */
    public LogPurgeJob() {}

    /** One scheduled run: delete every log that has exceeded its retention period. */
    public void execute(SchedulableContext ctx) {
        List<FB_Integration_Log__c> expired = findExpiredLogs(FAST_PATH_LIMIT);

        // allOrNone=false: a single locked or concurrently deleted record must not
        // abort the whole purge.
        Database.delete(expired, false);

        // The fast path was full, i.e. more logs are due for deletion than one
        // transaction may process: drain the rest in batch chunks.
        if (expired.size() == FAST_PATH_LIMIT) {
            Database.executeBatch(this, BATCH_SIZE);
        }
    }

    /**
     * Schedules this job to run every day at 02:00 under the name 'Log purge (nightly)'.
     * Note that System.schedule enforces unique job names, so abort an existing job
     * of the same name before calling this again.
     *
     * @return the Id returned by System.schedule (the Id of the CronTrigger record).
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }

    /**
     * All logs that have exceeded their retention period, capped at rowLimit rows.
     *
     * SOQL subtlety: `Level__c != 'ERROR'` does not match records whose Level__c is
     * blank, so blank logs are explicitly included in the 30-day rule.
     */
    private static List<FB_Integration_Log__c> findExpiredLogs(Integer rowLimit) {
        Datetime thirtyDaysAgo = Datetime.now().addDays(-30);
        Datetime oneHundredEightyDaysAgo = Datetime.now().addDays(-180);
        return [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c = null OR Level__c != 'ERROR'))
               OR (Level__c = 'ERROR' AND CreatedDate < :oneHundredEightyDaysAgo)
            LIMIT :rowLimit
        ];
    }

    // --------------------------------------------------------------------------------------------
    // Database.Batchable overflow path. The start() locator must use the same retention predicate
    // as findExpiredLogs(). A query locator is not subject to the 50,000-row SOQL limit, so it
    // can cover backlogs of any size.
    // --------------------------------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext ctx) {
        Datetime thirtyDaysAgo = Datetime.now().addDays(-30);
        Datetime oneHundredEightyDaysAgo = Datetime.now().addDays(-180);
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c = null OR Level__c != 'ERROR'))
               OR (Level__c = 'ERROR' AND CreatedDate < :oneHundredEightyDaysAgo)
        ]);
    }

    public void execute(Database.BatchableContext ctx, List<FB_Integration_Log__c> scope) {
        Database.delete(scope, false);
    }

    public void finish(Database.BatchableContext ctx) {
        // Nothing to do: the job is fire-and-forget.
    }
}
