public inherited sharing class AccountCountrySync {

    /**
     * Entry point for the Account after-update trigger.
     *
     * For every account whose BillingCountry changed, sets MailingCountry on that
     * account's contacts whose MailingCountry is blank or still equals the account's
     * previous BillingCountry. Contacts with any other MailingCountry ("working
     * abroad") and contacts of accounts whose BillingCountry did not change are
     * left untouched.
     *
     * Bulk-safe by design:
     *  - No SOQL or DML inside loops: one query and one DML per trigger invocation,
     *    regardless of batch size (MDM posts 200 accounts at a time).
     *  - The query is scoped to the affected accounts and filtered on MailingCountry
     *    in the database, so the 2.3M-row Contact table is never pulled into the
     *    transaction.
     *
     * @param newAccounts Trigger.new from the Account after-update event.
     * @param oldAccounts Trigger.oldMap: Id -> pre-update Account (source of the
     *                    previous BillingCountry).
     */
    public static void syncContactsOnBillingCountryChange(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        // 1. Find accounts whose BillingCountry actually changed; remember old -> new.
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Set<String> oldCountries = new Set<String>();

        for (Account acc : newAccounts) {
            Account before = oldAccounts == null ? null : oldAccounts.get(acc.Id);
            if (before == null) {
                // Defensive: in an after-update trigger every record has a "before" image.
                continue;
            }

            String oldCountry = before.BillingCountry;
            String newCountry = acc.BillingCountry;

            if (newCountry == oldCountry) {
                continue; // BillingCountry unchanged: this account's contacts are out of scope
            }

            newCountryByAccountId.put(acc.Id, newCountry);
            if (String.isNotBlank(oldCountry)) {
                oldCountries.add(oldCountry);
            }
        }

        if (newCountryByAccountId.isEmpty()) {
            return; // no BillingCountry changed in this batch, nothing to do
        }

        // 2. One bulkified query for every contact that could possibly qualify.
        //    The database does the heavy filtering: only contacts on changed accounts,
        //    and only those with a blank MailingCountry or a MailingCountry equal to one
        //    of the batch's previous countries. Contacts in any other country are never
        //    fetched. (If every changed account previously had a blank BillingCountry,
        //    oldCountries is empty, so run the blank-only variant to avoid binding an
        //    empty set to IN.)
        Set<Id> changedAccountIds = newCountryByAccountId.keySet();
        List<Contact> candidates;
        if (oldCountries.isEmpty()) {
            candidates = [
                SELECT Id, AccountId, MailingCountry
                FROM Contact
                WHERE AccountId IN :changedAccountIds
                  AND MailingCountry = null
            ];
        } else {
            candidates = [
                SELECT Id, AccountId, MailingCountry
                FROM Contact
                WHERE AccountId IN :changedAccountIds
                  AND (MailingCountry = null OR MailingCountry IN :oldCountries)
            ];
        }

        // 3. Re-verify each candidate against ITS OWN account's previous country.
        //    Required because the batch can contain several accounts with different old
        //    countries: a contact that matches another account's old country via the
        //    shared IN filter must be left alone.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : candidates) {
            String oldCountry = oldAccounts.get(con.AccountId).BillingCountry;
            Boolean qualifies = String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry;
            if (qualifies) {
                con.MailingCountry = newCountryByAccountId.get(con.AccountId);
                contactsToUpdate.add(con);
            }
        }

        // 4. Single DML statement. The handler never modifies Account, so the Account
        //    trigger cannot re-fire from this DML (no recursion guard needed).
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
