import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

/** Personal email domains that are not accepted for registration. */
const BLOCKED_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com',
]);

const WORK_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    /**
     * Keep each field's current value from its change event.
     * The data-field attribute identifies which reactive property to update.
     */
    handleChange(event) {
        const field = event.currentTarget.dataset.field;
        this[field] = event.detail.value;
    }

    handleRegister() {
        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );

        // Step 1: only work email addresses are accepted.
        const email = (this.email || '').trim();
        const domain = email.split('@').pop().toLowerCase();
        if (BLOCKED_EMAIL_DOMAINS.has(domain)) {
            emailInput.setCustomValidity(WORK_EMAIL_MESSAGE);
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report on every input so all invalid fields show messages at once.
        inputs.forEach((input) => input.reportValidity());

        // Step 3: stop if any input is still invalid.
        if (inputs.some((input) => !input.checkValidity())) {
            return;
        }

        // Step 4: register imperatively and toast the outcome.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company,
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success',
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error',
                    })
                );
            });
    }
}
